"""Measure STL booleans generated by v5_box_interference.scad (not fit proof)."""

from __future__ import annotations

import json
from pathlib import Path

import numpy as np

from surrogate_sim import load_binary_stl, mesh_topology


HERE = Path(__file__).resolve().parent


def measure(path: Path) -> dict:
    triangles = load_binary_stl(path).astype(np.float64)
    a, b, c = triangles[:, 0], triangles[:, 1], triangles[:, 2]
    signed_volume = np.einsum("ij,ij->i", a, np.cross(b, c)).sum() / 6.0
    topology = mesh_topology(triangles.astype(np.float32))
    if topology["nonmanifold_or_open_edges"]:
        raise AssertionError(f"Open boolean result: {path}")
    return {
        "mesh": str(path),
        "volume_mm3": round(float(abs(signed_volume)), 1),
        "volume_cm3": round(float(abs(signed_volume) / 1000), 3),
        "topology": topology,
    }


def main() -> None:
    rows = {}
    for key in ("splitter", "uvc_usb3"):
        path = HERE / f"v5-clash-{key}.stl"
        rows[key] = measure(path)
    (HERE / "v5-boolean-clash-results.json").write_text(
        json.dumps({"scope": "selected optimistic box locations, no connectors/cables/tolerances",
                    "results": rows}, indent=2) + "\n", encoding="utf-8"
    )
    for name, row in rows.items():
        print(name, row["volume_mm3"], "mm3")


if __name__ == "__main__":
    main()
